'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict'),cp=require('./portable-baseline.cjs'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..'),baselineRef='eb9c742';
const read=p=>fs.readFileSync(path.join(root,p),'utf8'),source=read('dist/scenes/toaster.js');
const baseline=cp.execFileSync('git',['show',baselineRef+':dist/scenes/toaster.js'],{cwd:root,encoding:'utf8'});
const clone=v=>JSON.parse(JSON.stringify(v)),hash=v=>crypto.createHash('sha256').update(v).digest('hex');
const results=[],samples=[];let checkedFrames=0,parityFrames=0,geometryComparisons=0;
function test(name,fn){try{fn();results.push({name,ok:true});}catch(error){results.push({name,ok:false,error:error.stack});}}
function make(code=source){let mounted=null,invalidations=0;const ctx={window:{MuseumObservation:{mountLesson(options){mounted=options;return{};}}},console,addEventListener(){},Math,Number};vm.createContext(ctx);vm.runInContext(read('dist/core.js'),ctx);vm.runInContext(code,ctx);const cfg=ctx.window.SCENES.toaster(),s=cfg.state,steps=new Set(),flashes=[];s.pal='mint';s.az=105;
 const ui={animate(fn){steps.add(fn);},invalidate(){invalidations++;},flash(t){flashes.push(t);}};cfg.setup?.(ui);
 const f={ctx,cfg,s,ui,steps,flashes,get mounted(){return mounted;},get invalidations(){return invalidations;},snap(){return cfg.lesson.read(s);},toggle(on){cfg.lesson.onToggle(s,on,ui);},choice(id){cfg.lesson.onChoice(s,id,ui);},advance(){cfg.lesson.onAdvance(s,ui);},act(id,data={}){cfg.acts[id](s,{dataset:data},ui);},level(n){cfg.buttons.find(b=>b.label==='选择焦度').choices(s)[n-1].onClick(s,ui);},frame(dt=.04){for(const fn of [...steps])if(fn(dt)===false)steps.delete(fn);},tick(seconds,dt=.04){for(let t=0;t<seconds-1e-9;t+=dt)this.frame(Math.min(dt,seconds-t));},finish(){let n=0;while(steps.size&&n++<4000)this.frame();assert.equal(steps.size,0,'drivers terminate');},render(yaw=45,pitch=35.264){vm.runInContext(`setCam(${yaw},${pitch});setLight(105);`,ctx);return cfg.scene(s,vm.runInContext('PALS.mint',ctx));}};return f;
}
function check(f){const before=JSON.stringify(f.s),l=f.snap(),o=f.cfg.observation.read(f.s),s=f.s;assert.equal(JSON.stringify(s),before,'reading does not mutate state');assert.equal(l.title,o.stage);assert(l.text.startsWith(o.text));assert.deepEqual(clone(l.active),clone(o.active));assert.deepEqual(clone(l.readouts),clone(o.readouts));assert.equal(l.completed,false);assert.equal(l.paused,false);assert.equal(l.pauseVisible,false);assert.equal(l.phase,s.phase);assert.equal(l.level,s.level);assert.equal(l.duration,3+s.level*2);assert.equal(l.progress,s.progress);assert.equal(l.lever,s.lever);assert.equal(l.slices,s.slices);assert.equal(l.made,s.made);assert.equal(l.powered,s.phase==='heating');assert.equal(l.busy,['loading','lowering','heating','popping','taking'].includes(s.phase));assert.equal(l.index,{empty:0,loading:0,loaded:1,lowering:1,heating:2,popping:3,ready:4,taking:4}[s.phase]);assert(l.label&&l.look);if(s.phase==='loading'){assert(l.text.includes('放稳后可调整焦度'));assert(!l.text.includes('本轮设定已锁定'));}assert(l.text.length<160,'compact explanation');assert(!/undefined|NaN|Infinity/.test(l.text));assert.equal(l.choices.filter(c=>c.id.startsWith('level-')).length,['empty','loaded'].includes(s.phase)?3:0);assert.equal(l.choices.some(c=>c.id==='stop'),['lowering','heating'].includes(s.phase));assert.equal(l.choices.some(c=>c.id==='reset'),s.phase!=='empty');assert(s.progress>=0&&s.progress<=1&&s.lever>=0&&s.lever<=1);assert([0,2].includes(s.slices));assert.equal(s.made%2,0);assert(f.steps.size<=2);checkedFrames++;return l;}
function equal(a,b,label){assert.deepEqual(clone(a.s),clone(b.s),label);assert.equal(a.steps.size,b.steps.size,label+' callbacks');parityFrames++;}
function sameGeometry(a,b,yaw=45,pitch=35.264){const actual=a.render(yaw,pitch);assert(!/NaN|undefined|Infinity/.test(actual));assert.equal(actual,b.render(yaw,pitch),`full SVG ${a.s.phase} ${yaw}/${pitch}`);geometryComparisons++;}
function finishPair(a,b,label,{geometry=false}={}){let n=0;while(a.steps.size||b.steps.size){assert(n++<4000,label+' terminates');a.frame();b.frame();equal(a,b,label);check(a);if(geometry)sameGeometry(a,b);if(n%8===0)samples.push(clone(a.s));}}
function loaded(f){f.act('load');f.finish();assert.equal(f.s.phase,'loaded');}
function targetPhase(f,phase){if(phase==='empty')return;loaded(f);if(phase==='loaded')return;f.act('start');for(let n=0;f.s.phase!==(phase==='taking'?'ready':phase)&&n<2000;n++)f.frame();if(phase==='taking'&&f.s.phase==='ready')f.act('collect');assert.equal(f.s.phase,phase);}

test('All preexisting state, scheduler/actions, bread geometry, clipping and depth sorting are byte-identical',()=>{for(const [label,slice]of [['controller',s=>s.slice(0,s.indexOf(' function aboveTop('))],['entire geometry',s=>s.slice(s.indexOf(' function aboveTop('),s.indexOf(' const observation='))],['observation except required title',s=>s.slice(s.indexOf(' const observation='),s.indexOf(s.includes(' // Optional live explanation:')?' // Optional live explanation:':' const text=(s,k)=>')).replace("title:'看动作懂原理'","title:'看原理'")]])assert.equal(hash(slice(source)),hash(slice(baseline)),label);const lessonSource=source.slice(source.indexOf(' // Optional live explanation:'),source.indexOf(' const text=(s,k)=>'));assert(!/requestAnimationFrame|setTimeout|setInterval|\.animate\(|lessonPaused/.test(lessonSource),'adapter cannot add a clock or pause');});
test('Default free play and nested lesson mount do not alter state or schedule animation',()=>{const f=make(),before=clone(f.s);assert.equal(f.cfg.observation.title,'看原理');assert.equal(f.snap().enabled,false);assert.equal(f.mounted.id,'toaster');assert.equal(f.mounted.linear,false);assert.deepEqual(clone(f.mounted.route),['放','压','烤','弹','取']);assert.equal(f.mounted.onPause,undefined);f.advance();f.choice('level-3');f.choice('reset');assert.deepEqual(clone(f.s),before);for(let n=0;n<20;n++){f.mounted.onToggle(true);assert.equal(f.snap().enabled,true);f.mounted.onToggle(false);}assert.deepEqual(clone(f.s),before);assert.equal(f.steps.size,0);check(f);});
test('Every frame of all three full cycles matches baseline state and full SVG, with lesson-only user controls',()=>{for(const n of [1,2,3]){const f=make(),old=make(baseline);f.toggle(true);f.choice('level-'+n);old.level(n);finishPair(f,old,'dial '+n,{geometry:true});f.advance();old.act('load');finishPair(f,old,'load '+n,{geometry:true});f.advance();old.act('start');const seen=new Set();let frame=0;while(f.steps.size||old.steps.size){f.frame();old.frame();equal(f,old,'bake '+n);check(f);sameGeometry(f,old);seen.add(f.s.phase);if(frame++%8===0)samples.push(clone(f.s));if(frame%17===0){const before=clone(f.s);f.toggle(false);f.toggle(true);assert.deepEqual(clone(f.s),before);}}assert.deepEqual([...seen],['lowering','heating','popping','ready']);assert.equal(f.s.progress,1);assert.equal(f.snap().powered,false);f.advance();old.act('collect');finishPair(f,old,'collect '+n,{geometry:true});assert.equal(f.s.phase,'empty');assert.equal(f.s.made,2);assert.equal(f.s.plateToast,[.25,.6,1][n-1]);assert.equal(f.steps.size,0);}});
test('Actual full-cycle snapshots are byte-identical at 24 viewpoints, including rear clipping and lid crossings',()=>{const a=make(),b=make(baseline);const selected=samples.filter((s,i)=>i%4===0||['loading','taking'].includes(s.phase));for(const state of selected){Object.assign(a.s,state);Object.assign(b.s,state);for(const yaw of [0,45,90,135,180,225,270,315])for(const pitch of [6,35.264,78])sameGeometry(a,b,yaw,pitch);}assert(selected.some(s=>s.phase==='loading'&&s.loadT>0&&s.loadT<1));assert(selected.some(s=>s.phase==='taking'&&s.takeT>0&&s.takeT<1));});
test('Fifty repeated main/invalid controls cannot duplicate insertion, restart heating or double collection',()=>{const f=make();f.toggle(true);for(const id of ['stop','reset','level-0','level-4','level-x','collect','not-real'])f.choice(id);assert.equal(f.s.phase,'empty');assert.equal(f.s.slices,0);f.advance();const at=clone(f.s);for(let n=0;n<50;n++){f.advance();f.choice('level-3');f.act('collect');f.act('load');}assert.deepEqual(clone(f.s),at);f.finish();f.advance();const heatingStart=clone(f.s);for(let n=0;n<50;n++){f.advance();f.choice('level-1');}assert.deepEqual(clone(f.s),heatingStart);f.finish();assert.equal(f.s.phase,'ready');f.advance();const collecting=clone(f.s);for(let n=0;n<50;n++){f.advance();f.act('collect');f.act('load');}assert.deepEqual(clone(f.s),collecting);f.finish();assert.equal(f.s.made,2);assert.equal(f.s.slices,0);for(let n=0;n<50;n++)f.act('collect');assert.equal(f.s.made,2);assert.equal(f.steps.size,0);check(f);});
test('Cancel before motion, during descent and during heating preserves baseline phase/colour, counts only after collection',()=>{for(const delay of [0,.04,.28,.6,2.6,6.2]){const f=make(),old=make(baseline);f.toggle(true);loaded(f);loaded(old);f.advance();old.act('start');f.tick(delay);old.tick(delay);equal(f,old,'before cancel');const progress=f.s.progress,lever=f.s.lever;f.choice('stop');old.act('stop');equal(f,old,'cancel');assert.equal(f.s.progress,progress);assert.equal(f.s.lever,lever);assert.equal(f.snap().powered,false);const stopped=clone(f.s);for(let n=0;n<20;n++){f.choice('stop');f.advance();}assert.deepEqual(clone(f.s),stopped);finishPair(f,old,'cancel settle',{geometry:true});assert.equal(f.s.phase,'ready');assert.equal(f.s.progress,progress);assert.equal(f.s.made,0);if(!delay)assert.equal(f.s.lift,0);f.advance();old.act('collect');finishPair(f,old,'cancel collect',{geometry:true});assert.equal(f.s.made,2);assert.equal(f.s.plateToast,progress*.6);}});
test('Reset from every phase retires stale work, preserves chosen level/count and cannot resurrect toast',()=>{for(const phase of ['loading','loaded','lowering','heating','popping','ready','taking']){const f=make(),old=make(baseline);f.toggle(true);f.level(3);old.level(3);f.finish();old.finish();if(phase==='loading'){f.act('load');old.act('load');f.tick(.32);old.tick(.32);}else{targetPhase(f,phase);targetPhase(old,phase);}assert.equal(f.s.phase,phase);f.choice('reset');old.act('reset');equal(f,old,'reset '+phase);assert.equal(f.snap().enabled,true);finishPair(f,old,'stale reset '+phase);assert.equal(f.s.phase,'empty');assert.equal(f.s.slices,0);assert.equal(f.s.made,0);assert.equal(f.s.level,3);f.advance();old.act('load');finishPair(f,old,'restart '+phase);f.advance();old.act('start');finishPair(f,old,'reheat '+phase);f.advance();old.act('collect');finishPair(f,old,'recollect '+phase);assert.equal(f.s.made,2);f.act('reset');old.act('reset');finishPair(f,old,'idle reset '+phase);assert.equal(f.s.made,2);}});
test('Rapid reset/restart without retiring old drivers retains a single main driver and correct inventory',()=>{const f=make(),old=make(baseline);f.toggle(true);for(let n=0;n<80;n++){f.advance();old.act('load');f.tick(.01);old.tick(.01);f.choice('reset');old.act('reset');equal(f,old,'rapid reset '+n);check(f);}f.advance();old.act('load');finishPair(f,old,'last reload');f.advance();old.act('start');finishPair(f,old,'last bake');f.advance();old.act('collect');finishPair(f,old,'last collect');assert.equal(f.s.made,2);assert.equal(f.s.slices,0);});
test('Mixed original controls stay frame-exact with lesson off/on; ready/empty rest needs no callbacks',()=>{const a=make(),b=make(baseline),ids=['load','level','start','stop','collect','reset'];let seed=619;for(let n=0;n<240;n++){seed=seed*16807%2147483647;const id=ids[seed%ids.length];a.toggle(n%3!==0);a.act(id);b.act(id);for(let k=0;k<seed%25;k++){a.frame();b.frame();equal(a,b,'mixed '+n);check(a);}}finishPair(a,b,'mixed settle');for(const state of ['ready','empty']){const f=make();f.toggle(true);loaded(f);f.advance();f.finish();if(state==='empty'){f.advance();f.finish();}const snap=clone(f.s),invalidates=f.invalidations;for(let n=0;n<500;n++)f.frame();assert.deepEqual(clone(f.s),snap);assert.equal(f.steps.size,0);assert.equal(f.invalidations,invalidates);check(f);}});
function integrated(){const f=require('./review-process-invariants.cjs').fixture('toaster'),d=f.document,proto=Object.getPrototypeOf(d);proto.focus=function(){d.activeElement=this;};proto.scrollIntoView=function(){};proto.contains=function(n){return n===this||this.children.some(c=>c.contains(n));};const dock=d.createElement('section'),primary=d.createElement('div'),extras=d.createElement('div');dock.className='play-dock';primary.id='btns';primary.className='actions';extras.className='dock-extras';dock.append(primary,extras);d.body.append(dock);f.mount();let audioResets=0;f.c.__lessonAudio={reset(){audioResets++;}};const core=read('dist/core.js'),hookStart=core.indexOf('  const isResetAction ='),hookEnd=core.indexOf('\n\n  const layerNodes=',hookStart);assert(hookStart>=0&&hookEnd>hookStart);vm.runInContext('{const audio=globalThis.__lessonAudio;const ui=globalThis.ui;'+core.slice(hookStart,hookEnd)+'}',f.c);const panel=f.ui.observation.panel,host=panel.parentElement;host.remove();extras.append(host);const guide=panel.querySelector('.toaster-guide');return{f,d,dock,primary,extras,panel,guide,get audioResets(){return audioResets;},read:()=>f.cfg.lesson.read(f.s),open(){f.toggle(panel,true);f.toggle(guide,true);},advance(){guide.querySelector('.mechanism-lesson-go').click();},choice(id){const b=guide.querySelector('[data-choice="'+id+'"]');assert(b,'UI choice '+id);b.click();return b;}};}
test('Production helper: default closed, main-left card, folded originals, non-linear route and clean exit/reentry',()=>{const t=integrated(),{f,panel,guide,primary,dock}=t,before=f.snapshot();assert.equal(panel.open,false);assert.equal(guide.open,false);assert.equal(t.read().enabled,false);assert.equal(f.pending,0);t.open();assert.equal(guide.parentElement,dock);assert.equal(primary.parentElement.className,'lesson-free-controls toaster-free-controls');assert.equal(primary.parentElement.open,false);assert.equal(f.snapshot(),before);assert.equal(guide.querySelector('.mechanism-lesson-hold').hidden,true);assert(guide.querySelector('.mechanism-lesson-title').textContent.startsWith('当前 · '));for(const dot of guide.querySelectorAll('.mechanism-lesson-route span'))assert.equal(dot.dataset.done,'false');assert.equal(guide.querySelectorAll('[aria-current="step"]').length,1);guide.querySelector('.mechanism-lesson-exit').click();assert.equal(primary.parentElement,dock);assert.equal(t.read().enabled,false);assert.equal(f.snapshot(),before);assert.equal(dock.querySelectorAll('#btns').length,1);t.open();assert.equal(f.snapshot(),before);f.finish();assert.equal(f.pending,0);});
test('Production helper: live controls/highlights share exact state, choices lock, and exit does not pause heating',()=>{const t=integrated(),{f,guide}=t;t.open();t.choice('level-3');f.finish();assert.equal(f.s.level,3);t.advance();for(let n=0;n<30;n++)t.advance();f.finish();assert.equal(f.s.phase,'loaded');t.advance();f.tick(.9);assert.equal(f.s.phase,'heating');assert.equal(guide.querySelector('.mechanism-lesson-go').getAttribute('aria-disabled'),'true');assert.equal(guide.querySelectorAll('[data-choice]').filter(b=>b.dataset.choice.startsWith('level-')).length,0);f.svg.innerHTML=f.render();f.ui.observation.update();assert.equal(f.svg.querySelector('[data-observe-part="toaster-heater"]').dataset.observeActive,'true');assert.equal(guide.querySelector('.mechanism-lesson-title').textContent,'当前 · 发热丝通电');const progress=f.s.progress;t.choice('stop');assert.equal(f.s.progress,progress);f.finish();assert.equal(f.s.phase,'ready');t.advance();f.finish();assert.equal(f.s.made,2);t.advance();f.finish();t.advance();f.tick(.9);const before=f.s.progress;guide.querySelector('.mechanism-lesson-exit').click();f.frame();assert(f.s.progress>before);assert.equal(t.read().enabled,false);t.open();assert.equal(t.read().phase,'heating');f.finish();assert.equal(f.s.phase,'ready');assert.equal(f.s.made,2);t.advance();f.finish();assert.equal(f.s.made,4);assert.equal(f.pending,0);});
test('Lesson reset invokes the original core lifecycle exactly once: quarter speed restores and audio resets',()=>{const t=integrated(),{f,panel,guide}=t;t.open();panel.querySelector('[data-rate="0.25"]').click();assert.equal(f.ui.simulationRate,.25);t.advance();f.tick(.24);assert.equal(f.s.phase,'loading');assert.equal(t.audioResets,0);t.choice('reset');assert.equal(f.s.phase,'empty');assert.equal(f.s.slices,0);assert.equal(f.ui.simulationRate,1);assert.equal(f.ui.observation.rate,1);assert.equal(t.audioResets,1);assert.equal(guide.open,true);assert.equal(t.read().enabled,true);f.finish();assert.equal(f.pending,0);t.choice('level-1');f.finish();t.advance();f.finish();t.advance();f.tick(.9);assert.equal(f.s.phase,'heating');assert.equal(t.audioResets,1,'ordinary lesson actions do not reset audio');panel.querySelector('[data-rate="0.25"]').click();assert.equal(f.ui.simulationRate,.25);t.choice('reset');assert.equal(t.audioResets,2);assert.equal(f.ui.simulationRate,1);f.finish();assert.equal(f.s.phase,'empty');assert.equal(f.s.made,0);assert.equal(f.pending,0);});
test('Production RAF: hidden-page pause, observer close, quarter speed, observer disposal and fresh entry retain existing semantics',()=>{const t=integrated(),{f,panel,guide}=t;t.open();t.advance();f.finish();t.advance();f.tick(.9);const before=f.snapshot();f.document.hidden=true;f.document.emit('visibilitychange');f.tick(10);assert.equal(f.snapshot(),before);assert.equal(f.pending,0);f.document.hidden=false;f.document.emit('visibilitychange');f.frame();assert(f.s.progress>JSON.parse(before).progress);f.toggle(panel,false);assert.equal(guide.open,false);assert.equal(t.read().enabled,false);assert.equal(t.primary.parentElement,t.dock);t.open();const normal=f.s.progress;panel.querySelector('[data-rate="0.25"]').click();f.tick(.8);assert(f.s.progress-normal<.04,'quarter-speed mechanism uses existing rate');f.toggle(panel,false);assert.equal(f.ui.simulationRate,1);const progress=f.s.progress;f.ui.observation.dispose();assert.equal(t.primary.parentElement,t.dock);assert.equal(t.dock.querySelector('.toaster-guide'),null);f.frame();assert(f.s.progress>progress,'disposing explanation does not stop existing animation');f.finish();assert.equal(f.s.phase,'ready');assert.equal(f.pending,0);assert(read('dist/shell.js').includes('location.reload()'),'real route changes reload the document, outside this DOM harness');const fresh=integrated();assert.equal(fresh.f.s.phase,'empty');assert.equal(fresh.f.s.made,0);assert.equal(fresh.read().enabled,false);assert.equal(fresh.panel.open,false);assert.equal(fresh.guide.open,false);});
const report={baselineRef,scope:'toaster optional lesson adapter and new focused QA only',browser:false,limits:'Production callbacks, full SVG comparison and existing production observation/RAF with DOM doubles. Not browser/layout/accessibility-device evidence. Parent must complete real desktop/mobile and keyboard QA before publication.',checkedFrames,parityFrames,geometryComparisons,sampledAnimationStates:samples.length,results};
